import{_ as i}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as o,d as t,o as l}from"./app-DyZxLOeY.js";const s={};function a(n,e){return l(),o("div",null,e[0]||(e[0]=[t('<h1 id="section-19" tabindex="-1"><a class="header-anchor" href="#section-19"><span>Section 19</span></a></h1><h2 id="_1" tabindex="-1"><a class="header-anchor" href="#_1"><span>1.</span></a></h2><ol><li>Zari has to read five chapters <strong>of</strong> this book tonight.</li><li>This app is a bit confusing, isn&#39;t it?</li><li>You take intermediate <strong>physics</strong> before advanced physics.</li><li>Sorry, but that answer is incorrect.</li><li>All the university buildings are <strong>on</strong> campus.</li><li>Hey, Kevin! Did you finish your essay? The professor told us to write two pages, right? I only have one page right now. <ol><li>The speaker is Kevin&#39;s classmate.</li></ol></li><li>My professor has asked three of us to do research with her next fall. I&#39;m very excited because we can learn so much from her! <ol><li>He&#39;s excited because he&#39;s going to learn more.</li></ol></li><li>Professor Lee told us to change our incorrect answers.</li><li>I always ask Anna <strong>for</strong> help. I asked her <strong>to</strong> take me to my dorm.</li><li>Which class should I pick?</li><li>Yes, but it doesn&#39;t smell good. We shouldn&#39;t use it.</li><li>We only have <strong>a few</strong> hot dogs and some strawberries. Let&#39;s order delivery …</li><li>I don&#39;t want to cook tonight. Let&#39;s order delivery!</li><li>What&#39;s inside that plastic container?</li><li>These cans are full of tuna. And they&#39;re so cheap!</li><li>We have so <strong>many</strong> containers in the fridge, but there isn&#39;t <strong>much</strong> food in there.</li><li>I&#39;m so hungry, but there&#39;s nothing to eat in the fridge, only a few old potatoes. I have an idea! Let&#39;s order delivery! <ol><li>What&#39;s the speaker&#39;s idea?</li><li>to buy dinner</li></ol></li><li>Do we need so <strong>many</strong> cans of tuna? We don&#39;t have <strong>much</strong> time now. Can we buy them later?</li><li>Something in the fridge smells awful! Maybe it&#39;s the tuna salad. It looks <strong>old</strong>. Oh, and it smells bad. Nobody should eat this! <ol><li>Right now, the speaker is looking inside the fridge.</li></ol></li><li>I always use this delivery app. <ol><li>Me too! They&#39;re always so fast!</li></ol></li><li>Our neighbor is cooking something and it smells delicious!</li><li>How long has the chicken been in that container?</li><li>Mia is allergic to bread. If she eats it, she gets sick.</li><li>I always check the ingredients because I can&#39;t eat eggs.</li><li>Wow, this food tastes so good! It&#39;s delicious.</li><li>I love this restaurant! Their sandwiches taste great!</li><li>This app is the best way to order delivery.</li><li>Every time Mia order food, she has to check the ingredients. If a sauce has milk in it, she can&#39;t eat it because she&#39;s <strong>allergic</strong> to milk. <ol><li>What does Mia have to check?</li><li>what is in a dish.</li></ol></li><li>I have a delivery app on my phone, but there are very few restaurants in this neighborhood.</li><li>OK, let&#39;s order one cheese pizza. Kevin and Ben are allergic to cheese, so we&#39;ll get a few burgers, too. What else? Maybe a salad? <ol><li>Kevin and Ben can&#39;t eat cheese.</li></ol></li><li>Lisa, <strong>very few</strong> restaurants are open today. Can I make you a burger instead?</li><li>I can eat very <strong>few</strong> dishes because I&#39;m allergic to almost everything.</li><li>Yes, of course. But it tasted terrible.</li><li>That Italian restaurant knows the perfect way to make pizza!</li><li>Are their <strong>salads</strong> good? <ol><li>Yes! Their ingredients are so fresh!</li></ol></li><li>This menu has very little good food <strong>on</strong> it. Can we try somewhere else?</li><li>Oh, this chicken soup doesn&#39;t look bad in the photo. I think I&#39;ll order it.</li><li>OK, Maria, what should we order? The steak looks good, but the chicken looks good, too. Maybe we can order both! What do you think? <ol><li>They are trying to decide something.</li></ol></li><li>It&#39;s a great restaurant, but there&#39;s very <strong>little</strong> information online, so very <strong>few</strong> people know it.</li><li>It&#39;s late, and very <strong>few</strong> restaurants are still open. We have very <strong>little</strong> time to order.</li><li>Just talking about food makes me hungry!</li><li>That pineapple is green.</li><li>This jar is empty. I need to buy some cookies.</li><li>Great idea. How about pineapples.</li><li>Grilled vegetables look so good in this picture.</li><li>Do they really serve drinks in coconuts?</li><li>This yogurt smells <strong>sour</strong>. I&#39;m going to add some honey.</li><li>My favorite beverage is orange juice.</li><li>Without sugar, <strong>lemonade</strong> can be very sour.</li><li>Do we have something to drink at home? Grilled fish makes me thirsty.</li></ol><h2 id="_2" tabindex="-1"><a class="header-anchor" href="#_2"><span>2.</span></a></h2><ol><li>Coconut water smells so fresh. That&#39;s why I like it.</li><li>Some beverages make you more thirsty. Did you know that? For example, after you drink coffee or soda, your body will want more water. <ol><li>The speaker&#39;s talking about how the body works.</li></ol></li><li>That juice in the fridge doesn&#39;t smell good. Let&#39;s order beverages, too.</li><li>Wow, Amy! Look at all the different flavors of sodas! There&#39;s mango, strawberry, pineapple, grape, or lemon. Which flavor do you want? <ol><li>There are many kinds of soda.</li></ol></li><li>Lisa&#39;s making coconut cake! Watching her bake always makes me hungry.</li><li>Do you want to order a drink? I think their lemonade is too sour, but they have coconut water, and it&#39;s really good! You should try it! <ol><li>The speaker thinks their coconut water is good.</li></ol></li><li>Would you like to order some soda? The pizza can make us thirsty.</li><li>I&#39;m getting a sandwich and fries. Should I get a small beverage or large one? Fries make me thirsty, so I should probably get a <strong>large</strong> drink. <ol><li>The speaker decides to buy a big drink.</li></ol></li><li>Let&#39;s order beverages too because <strong>Asian</strong> food always make me thirsty.</li><li>Look, they have ten different flavors of soda!</li><li>How many flavors of soda do you have?</li><li>Have you tried their sour lemon soda?</li><li>The total is fifty dollars.</li><li>What&#39;s the location of the pizza party? I don&#39;t know where it is.</li><li>Waiting for the delivery always makes me nervous!</li><li>Seeing the expensive total made us nervous.</li><li>Ask for utensils because all our forks are dirty.</li><li>I don&#39;t have any forks or knives at home. Can you please put some <strong>utensils</strong> in the bag?</li><li>Ordering food on an app makes me nervous! Maybe I&#39;ll order the wrong thing, or there will be problem with my phone. I prefer going out. <ol><li>The speaker doesn&#39;t like ordering online.</li></ol></li><li>The total was only ten dollars! The pizza looked big online, but it is not big.</li><li>Which payment method should I use, credit card or cash? I know — I&#39;ll pay with a credit card now and give the delivery guy a cash tip later. <ol><li>The speaker is deciding how to pay.</li></ol></li><li>This soup smells sweet, but I don&#39;t think it is sweet. Here are utensils if you want to try!</li><li>Last time I ordered food from this restaurant, they sent very small plastic utensils. The knife and fork broke when I tried to cut my food! <ol><li>What was wrong?</li><li>The utensils were cheap.</li></ol></li><li>There are two payment methods we can use to buy the food.</li><li>Ordering food is making Zari hungry!</li><li>Their food is good, but the location is too far from us.</li><li>Cash, check, and credit card are all payment methods.</li><li>The restaurant&#39;s location is on the other side of town.</li><li>Here is our location on the map.</li><li>I didn&#39;t have any food or beverages today. Watching you eat is making me hungry!</li><li>I have very little time and I&#39;m hungry, but there are very few good restaurants here.</li><li>Their chocolate ice cream tastes great.</li><li>This salad smells terrible, don&#39;t eat it.</li><li>我不想要最后一颗草莓。我甚至不喜欢水果。 <ol><li>I don&#39;t want the last strawberry. I don&#39;t even like fruit.</li></ol></li><li>Drinking soda makes you more thirsty.</li><li>I&#39;ll order strawberry soda, and you?</li><li>The total is forty dollars.</li><li>We have very <strong>little</strong> food in the fridge, but very <strong>few</strong> restaurants are open!</li><li>I opened the jar of food, but it was empty. Let&#39;s just order delivery!</li><li>There are different ways to pay online.</li><li>This conversation is making me hungry.</li><li>What&#39;s in that container?</li><li>For the first time, I&#39;m going on an adventure!</li><li>My daughter is a traveler, too. She visits a new country every month. <ol><li>Wow, how cool! Where is she now?</li></ol></li><li>The plane will land soon.</li><li>Are you traveling to the US for the first time? <ol><li>Yes, I&#39;ve never been there before.</li></ol></li><li>My dad can&#39;t go, so I&#39;m flying solo!</li><li>Do you only have this small backpack? <ol><li>Yes, traveling without luggage is much cheaper.</li></ol></li><li>I&#39;m traveling with friends for the first time. I usually travel solo.</li><li>My suitcase is much heavier than my backpack.</li></ol><h2 id="_3" tabindex="-1"><a class="header-anchor" href="#_3"><span>3.</span></a></h2><ol><li>I&#39;m traveling solo for the first time, so I&#39;m very excited!</li><li>Our plane just landed!</li><li>Our flight lands at three o&#39;clock, right?</li><li>Many travelers take this train, so it&#39;s usually very crowded.</li><li>The flight is so long, and I&#39;m bored. My movie is <strong>funny</strong>, but that guy&#39;s movie is much <strong>funnier</strong>!</li><li>I&#39;ve never seen so many travelers at the airport!</li><li>I usually travel solo because I don&#39;t like to travel with people.</li><li>When does our flight land?</li><li><strong>Travelers</strong> need trains and hotels.</li><li>You can get your luggage at the airport after arrival.</li><li>Excuse me, do you know our arrival time? <ol><li>We should be in New York at 3 p.m.</li></ol></li><li>Why is the line at passport control so long? <ol><li>Well, five flights arrived at the same time.</li></ol></li><li>Passport control is much more crowded when the airport is busy.</li><li>机场班车从那里出发? <ol><li><strong>Where</strong> does the airport shuttle <strong>leave from</strong>?</li><li>The stop is in front of Exit 3.</li></ol></li><li>My suitcase is too heavy, so I can&#39;t walk much farther.</li><li>Can I get on a bus here? <ol><li>No, it stops over there, near the gift shop.</li></ol></li><li>我的酒店在那边。你能带我去吗？ <ol><li>My hotel is <strong>over</strong> there. Can you <strong>take</strong> me please?</li></ol></li><li>I&#39;m going to take the taxi. It&#39;s <strong>much</strong> more comfortable <strong>than</strong> taking a shuttle.</li><li>I only check your passport and visa at the passport control.</li><li>My hotel is over there! It&#39;s much more expensive than other hotels in this city.</li><li>This computer screen shows all the arrivals.</li><li>The passport control here is <strong>much</strong> more crowded <strong>than</strong> those in Japan.</li><li>Our flight&#39;s arrival was delayed.</li><li>Yes, the shuttle comes every fifteen minutes.</li><li>If you walk a little farther, you&#39;ll see the bathroom.</li><li>I haven&#39;t unpacked my suitcase yet.</li><li>Do I need to pay extra for a double room? <ol><li>Yes, but it&#39;s only eight dollars.</li></ol></li><li>I unpacked my bags, but I can&#39;t find my hat!</li><li>Here&#39;s your room key! Would you like to pay for breakfast? <ol><li>Oh, does it cost extra?</li></ol></li><li>I spent extra for a <strong>bigger</strong> room.</li><li>How did you unpack so quickly? <ol><li>Well, I didn&#39;t bring many clothes.</li></ol></li><li>I need to unpack my bag, but I&#39;m late!</li><li>This hotel has a laundry room, so I can wash my clothes.</li><li>I&#39;d like to reserve a room for two nights, please.</li><li>We don&#39;t let guests use the pool after 8 o&#39;clock.</li><li>I want to use the laundry room. Do you let guests use the laundry room?</li><li>I need to reserve a room, but no one&#39;s here!</li><li>I want to reserve a room, but the hotel doesn&#39;t let guests reserve rooms online.</li><li>We have a laundry room if you need to wash clothes.</li><li>I thought I reserved a no-smoking room!</li><li>My pants are dirty, so I have to do laundry.</li><li>If you want to stay another night, it will cost extra.</li><li>It&#39;s very easy to use the public transportation in the city.</li><li>Is it easy to use public transportation here? <ol><li>Oh yes, there are lots of buses and <strong>trams</strong>!</li></ol></li><li>Does a bus or other type of public transportation go there?</li><li>The weather is perfect today. Do you have tables outside? <ol><li>Of course! You can sit on the patio.</li></ol></li><li>We can use public transportation or rent a car.</li><li>I&#39;m really hungry. Where can I have lunch around here? <ol><li>The nearby coffee shop has great sandwiches!</li></ol></li><li>To ride the subway, you have to pay the <strong>fare</strong>.</li><li>Excuse me, how much is the bus fare to the city?</li></ol><h2 id="_4" tabindex="-1"><a class="header-anchor" href="#_4"><span>4.</span></a></h2><ol><li>The bus <strong>fares</strong> here are higher than in my hometown. <ol><li>Really? How much do you usually pay?</li></ol></li><li>It&#39;s sunny today. Let&#39;s go outside and have lunch on the patio!</li><li>I was going <strong>to sit</strong> there, but they don&#39;t let people <strong>sit</strong> on the patio.</li><li>The waiter let me <strong>try</strong> the wine and it was delicious!</li><li>They let me <strong>try</strong> their cake and it was good! I was going <strong>to try</strong> the cookie too, but I was full.</li><li>Of course, you can sit on the patio.</li><li>The bus <strong>fare</strong> is only two <strong>dollars</strong>!</li><li>The museum is nearby, so we can walk there!</li><li>Paris is the city that I liked best.</li><li>Do you feel homesick? <ol><li>Yes, I miss my parents.</li></ol></li><li>What you like best is your favorite thing.</li><li>Traveling solo is actually fun! <ol><li>On the other hand, you miss your friends.</li></ol></li><li>Traveling solo is cool, but I&#39;m a little homesick.</li><li>What continents have you visited? <ol><li>I&#39;ve traveled around Europe and South America.</li></ol></li><li>Sarah&#39;s dad has let her borrow his car for her first solo trip.</li><li>Why do you look so excited? <ol><li>A famous actor has let me take a photo with him.</li></ol></li><li>Bea really enjoyed her trip! On the other hand, she&#39;s very <strong>tired</strong>.</li><li>I&#39;ve traveled <strong>far</strong> away from home, but this is the <strong>farthest</strong> away I&#39;ve traveled alone!</li><li>Spain was the country I liked best. I really enjoyed the buildings there.</li><li>I like to travel far away from where I live. France is the farthest away I&#39;ve traveled.</li><li>Which continent do you want to <strong>visit</strong> next time?</li><li>This is the <strong>farthest</strong> away I&#39;ve ever been. I don&#39;t usually travel <strong>far</strong> from home.</li><li>The first week was exciting, but then I felt homesick.</li><li>Since I arrived, my friend has <strong>let</strong> me sleep on her couch many times.</li><li>Africa is the only <strong>continent</strong> that I haven&#39;t visited.</li><li>Bea really enjoyed her trip! Oh the other hand, she&#39;s very tried.</li><li>Going by taxi is <strong>much</strong> more comfortable <strong>than</strong> using an airport shuttle.</li><li>Bring some cash for train fare and snacks.</li><li>What&#39;s the <strong>farthest</strong> away from home that you&#39;ve traveled? <ol><li>I think it&#39;s here. My flight was twenty hours!</li></ol></li><li>It might be dangerous to travel alone. <ol><li>Yes, but, on the other hand, it&#39;s so much fun!</li></ol></li><li>Which museum did you like best? <ol><li>The history museum was fun!</li></ol></li><li>Solo means alone.</li><li>They let their guests use the hotel gym only two hours a day.</li><li>This app is the <strong>fastest</strong> way to order pizza.</li><li>Take a few containers and put some rice in them.</li><li><strong>Did</strong> you reserve a room online?</li><li>Next semester, I&#39;ll attend all his lectures!</li><li>The description is in German.</li><li>A <strong>laboratory</strong> is a building where science professors wear long, white coats and do chemistry projects with special machines. <ol><li>laboratory: a place to study science</li></ol></li><li>Some people like the taste of <strong>sour</strong> foods. Lemons taste very <strong>sour</strong>. <ol><li>sour: not sweet</li></ol></li><li>Coconuts grow on trees. A coconut is hard and brown on the outside, but soft and white inside. <ol><li>coconut: a round fruit</li></ol></li><li>This food delivery app is asking for our location.</li><li>Let&#39;s have lunch in the <strong>dining hall</strong> after class.</li><li>Lily is writing an essay <strong>for</strong> her English class.</li><li>Let&#39;s review for the Chinese test. What is this word?</li><li>We have very little money, so we should order something cheap.</li><li>If you are <strong>allergic to</strong> a kind of food, you get sick when you eat it. <ol><li><strong>allergic to</strong>: not able to eat</li></ol></li><li>What is the meaning of your name?</li><li>A long book usually has many shorter <strong>chapters</strong>. <ol><li>chapter: a part of a book</li></ol></li><li>Africa isn&#39;t a country, it&#39;s a <strong>continent</strong>! <ol><li>continent: a large area of many countries</li></ol></li></ol><h2 id="_5" tabindex="-1"><a class="header-anchor" href="#_5"><span>5.</span></a></h2><ol><li>Wow! This hotel room is nice! It even has a little fridge full of drinks! They probably cost extra. I&#39;ll ask the staff at the front desk. <ol><li>The speaker thinks the room looks good.</li></ol></li><li>The exam is <strong>similar</strong> to the homework. The questions are the same.</li><li>I watched a cooking show after work. It made me <strong>hungry</strong>.</li><li>Just walk a <strong>little</strong> farther, you can&#39;t miss it.</li><li>If something is <strong>confusing</strong>, it is difficult to understand. <ol><li><strong>confusing</strong>: without a clear reason</li></ol></li><li>The hotel let me change my room yesterday.</li><li>The exam has a <strong>written</strong> part, so I will bring a pen and paper to write with. <ol><li><strong>written</strong>: something you write</li></ol></li><li>When you enter a new country, the airport workers check your passport at <strong>passport control</strong>. <ol><li>passport control: a place for an ID check</li></ol></li><li>Choose our location on the map.</li><li>The subway is a kind of <strong>public transportation</strong>. Anybody can pay a few dollars to ride it. <ol><li><strong>public transportation</strong>: buses, trains, and subways</li></ol></li><li>Lily doesn&#39;t want that sandwich because she&#39;s allergic to cheese.</li><li>Sugar has a sweet <strong>flavor</strong>. Pizza has a salty flavor. <ol><li>flavor: how something tastes</li></ol></li><li>A <strong>description</strong> is when you explain what something is or how somebody looks in few words. <ol><li>description: a short report</li></ol></li><li>This is the <strong>intermediate</strong> class, right?</li><li>There is a really nice dining hall on campus.</li><li>A <strong>patio</strong> is a comfortable place where you can sit and eat. It&#39;s outside of a building or house. <ol><li>patio: somewhere you relax outside</li></ol></li><li>Yes, but we need to get our <strong>certificates</strong> first.</li><li>Planes take off and leave one airport. A few hours later, they land at another airport. <ol><li>land: for a plane to arrive</li></ol></li><li>I walked over there, but I didn&#39;t see any <strong>taxis</strong>.</li><li>Two <strong>similar</strong> things look or feel almost the same. <ol><li>similar: not very different</li></ol></li><li>Does the test include a written essay?</li><li>A <strong>traveler</strong> is a person who travels. <ol><li>traveler: somebody who takes trips</li></ol></li><li>Are you going to the dining hall now?</li><li>Do you always travels solo?</li><li>I need to pick three classes for next <strong>semester</strong>.</li><li>The professor told the college students to write two essays.</li><li>Hurry up, we&#39;re late.</li><li>I need to attend my lecture now, bye.</li><li>我需要去市政厅。 <ol><li>I need to go to <strong>city hall</strong>.</li></ol></li><li>Would you like to go into town with me?</li><li>We visited that mosque in two thousand ten.</li><li>They&#39;re at the gallery, which is near the city center.</li><li>This railroad has been here for twenty years.</li><li>He watched a film, which was long and boring.</li><li>We should go shopping in town.</li><li>Here&#39;s the White House, which was built in 1792.</li><li>This is my favorite place in Washington, DC.</li><li>Do you like watching <strong>documentaries</strong>?</li><li>That is a model of a <strong>mosque</strong>.</li><li>The museum is on First Street, which is very close.</li><li>Are you ready to continue?</li><li>Are you new in town?</li></ol><h2 id="_6-unit-3-talk-about-the-chores" tabindex="-1"><a class="header-anchor" href="#_6-unit-3-talk-about-the-chores"><span>6. Unit 3 : Talk about the <strong>chores</strong></span></a></h2><h3 id="discuss-your-work-experience" tabindex="-1"><a class="header-anchor" href="#discuss-your-work-experience"><span>Discuss your work experience</span></a></h3><ol><li>我们应该打扫厨房，因为看起来很乱。 <ol><li>We should clean the kitchen because it looks <strong>messy</strong>.</li></ol></li><li>嗯，我上次吸过地板了！ <ol><li>Well, I vacuumed the floors last time!</li></ol></li><li>听音乐能让我打扫得更快！ <ol><li>Listening to music makes me clean faster.</li></ol></li><li>我喜欢有洗碗机，因为它能把碗都洗好。 <ol><li>I like having a dishwasher because it does the work for you.</li></ol></li><li>是啊，我小时候必须用手洗碗。 <ol><li>Yeah, when I was a kid, I had to wash the dishes by hand!</li></ol></li><li>当我们有客人时， 我的父母要我在厨房帮忙。 <ol><li>When we had guests, my parents <strong>made</strong> me help in the kitchen.</li></ol></li></ol><h3 id="重点" tabindex="-1"><a class="header-anchor" href="#重点"><span>重点</span></a></h3><p>Talk in an online meeting</p><ol><li>你星期一不总是在办公室吗？ <ol><li>Aren&#39;t you always in the office on Monday<strong>s</strong>?</li></ol></li><li>不，我每星期有两天在家工作。 <ol><li>No, I work from home two days a week.</li></ol></li><li>艾玛，你穿了新衣服吗？ <ol><li>Are you wearing a new outfit, Emma?</li></ol></li><li>我们听不到你，本， 因为你静音了。 <ol><li>We can&#39;t hear you, Ben, because you&#39;re <strong>on mute</strong>.</li></ol></li><li>所有人都收到今天会议的议程了吗？ <ol><li>Did everyone get the <strong>agenda</strong> for today&#39;s meeting?</li></ol></li><li>是的，我有几个点子要跟团队分享。 <ol><li>Yes, I have a couple of ideas to share with the group.</li></ol></li></ol><h3 id="content" tabindex="-1"><a class="header-anchor" href="#content"><span>Content</span></a></h3><ol><li>When you <strong>have a good feeling about</strong> tomorrow, you think tomorrow will be a great day. <ol><li>have a good feeling: feel good</li></ol></li><li>I have a good feeling about this job. I think the boss likes me!</li><li>If you speak many languages, you have language <strong>skills</strong>. If you cook well, you have cooking <strong>skills</strong>. <ol><li>skill: something you&#39;re good at</li></ol></li><li>Her skills will be very <strong>useful</strong> in our workplace.</li><li>我需要多加练习，因为如果我的艺术技能很差，我就无法得到这份工作。 <ol><li>I need to practice a lot because I can&#39;t get this job if my <strong>art</strong> skills are terrible.</li></ol></li><li>When you want to <strong>stop working a job</strong>, you <strong>quit</strong>. <ol><li>quit your job: leave your job</li></ol></li><li>If you hate working here so much, then you should just quit.</li><li>I want to quit my job because it&#39;s too boring.</li><li>To get a job, you need to do an <strong>interview</strong>. You meet with a manager to show that you can do the job. <ol><li>interview: a meeting to answer questions.</li></ol></li><li>I have a job interview, so I&#39;m preparing for the <strong>questions</strong> they&#39;ll <strong>ask</strong> me.</li><li>I have a good feeling about my interview.</li><li>Your interview is today, right? <ol><li>Yes! And I have a good feeling about it.</li></ol></li><li>On your <strong>resume</strong>, you explain where you&#39;ve studied and worked. It&#39;s a document for applying for jobs.</li><li>Sorry, I can&#39;t meet you tonight because I didn&#39;t finish my resume.</li><li>Does your resume include all your skills?</li><li>I&#39;m applying for a new job. I really want to work there.</li><li>Have you already applied for the job? <ol><li>Yes, I have. I emailed them yesterday.</li></ol></li><li>On the <strong>education</strong> part of your resume, you write the universities and schools where you have studied. <ol><li>education: what you&#39;ve learned and where</li></ol></li><li>I completed my education in 2012.</li><li>Can you tell us about your education? <ol><li>Of course! I studied design in college.</li></ol></li><li>A <strong>responsible</strong> person always arrives on time and does their job well. <ol><li>responsible: careful and timely</li></ol></li><li>Emily is so responsible. She always does a good job.</li><li>We&#39;re looking for a responsible person for our team. Can you clean this mess?</li><li>We&#39;re looking for a very responsible person.</li><li>In an <strong>engineering</strong> program, you learn how to build things with math and physics. <ol><li><strong>engineering</strong>: the science of how to build</li></ol></li><li>I started college in 2020. Since then, I&#39;ve taken many engineering classes.</li><li>I studied engineering at the university.</li><li>You know a lot about our company! <ol><li>Well, I&#39;ve done some research.</li></ol></li><li>I&#39;ve always understood math. It was my favorite subject in school.</li><li>I got a new job last year. Since then, I&#39;ve done a lot of work.</li><li>Next question, how many projects have you done this year?</li><li>You have done <strong>a great job</strong> on your resume. They&#39;re going to love you!</li><li>我一生的大多数时间都能听懂英语。 <ol><li>I&#39;ve understood English most of my life.</li></ol></li><li>I&#39;ve always understood business.</li><li>A <strong>career</strong> is a path from one job to another. Over time, your work becomes a big part of your life. <ol><li>career: growing work experience</li></ol></li><li>I&#39;m a famous actor now, but I began my career at a small theater years ago.</li><li>Lisa, why do you want to change your career?</li><li>You work <strong>a part-time job</strong> for less than forty hours a week. <ol><li>part-time: for some of your time</li></ol></li><li>It&#39;s a part-time job, so you&#39;ll work only on Mondays. Is that OK?</li><li>Emily <strong>quit</strong> her last job because she didn&#39;t like it. <ol><li>quit: left</li></ol></li><li>Lily <strong>quit</strong> because she hated her job.</li><li>You <strong>quit</strong> that job because you didn&#39;t get along with your boss, correct? <ol><li>Yes, that&#39;s right. Nobody in the office liked him.</li></ol></li><li>Today is my first day <strong>at</strong> my job. Finally, my new life has <strong>begun</strong>! <ol><li><strong>begun</strong>: started</li></ol></li><li>Thank you very much, we&#39;ll call you next week. <ol><li>But the interview has just begun…</li></ol></li><li>The interview has just begun, and I like you already!</li><li>I&#39;ve done two or three part-time jobs since I <strong>completed</strong> my education.</li><li>I&#39;ve done this job since I graduated from college.</li><li>That was my first job since I moved here ten years ago.</li><li>I&#39;ve worked there since I finished college.</li><li>I was a taxi driver, but then I changed careers.</li></ol><h2 id="_7" tabindex="-1"><a class="header-anchor" href="#_7"><span>7.</span></a></h2><ol><li>An <strong>airline</strong> is a company that flies airplanes and sells plane tickets. <ol><li>airline: airplane business</li></ol></li><li>Since he began working for the airline, he has traveled to many countries.</li><li>American bosses give workers pay and <strong>benefits</strong> like vacation time and lower prices at the doctor&#39;s. <ol><li>benefits: something nice for workers</li></ol></li><li>What kind of benefits do workers receive?</li><li>The company will pay for my dentist, right? <ol><li>Of course! We have other benefits, too!</li></ol></li><li>If <strong>it sounds like</strong> a good idea, you think it is a good idea. <ol><li>it sounds like: it could be</li></ol></li><li>That sounds like a plan.</li><li>That sounds like a great job!</li><li>For <strong>a full-time job</strong>, you usually work forty hours a week. <ol><li>full-time: takes all your working time</li></ol></li><li>I still work full-time at my other job, so I&#39;m really tired.</li><li>How many hours a week will I need to work? <ol><li>It&#39;s a full-time job, so about forty.</li></ol></li><li>He has quit his job to travel around Europe.</li><li>You&#39;ve just quit your old job. What was the problem? <ol><li>I wanted to do something new.</li></ol></li><li>In the past ten years, I have quit ten jobs.</li><li>You have quit your part-time job already, right? Can you start next week?</li><li>I&#39;ve worked as a pilot for ten years. <ol><li>What airlines have you worked for?</li></ol></li><li>I&#39;ve worked for six different airlines since 2010.</li><li>If you are happy with the pay, hours, and boss, then you should <strong>accept the job</strong>. <ol><li>accept: say yes to</li></ol></li><li>To <strong>make a decision</strong> is to decide. <ol><li>decision: what you choose</li></ol></li><li>I need to think about it before I make a decision.</li><li>When someone <strong>contacts</strong> you, they send you a message or call you. <ol><li>contact: speak to</li></ol></li><li>When you <strong>sign</strong> a document, you write or type your name on it. <ol><li>sign: put your name on the page</li></ol></li><li>I&#39;m busy now, but I will sign the document later.</li><li>Are you ready to sign the documents?</li><li>When the boss is <strong>away</strong>, please ask customers to call again later. <ol><li>away: not here</li></ol></li><li>My manager is away for two weeks, so I will start my job next month.</li><li>You need to sign here.</li><li>Can you start on Monday? <ol><li>Sorry, I&#39;ll be away next week.</li></ol></li><li>Grandma can contact us <strong>on</strong> this app.</li><li>Have you accepted the job? <ol><li>Yes! I&#39;m starting on Monday.</li></ol></li><li>Has your boss contacted you yet?</li><li>I can&#39;t decide! I&#39;ve never <strong>understood</strong> how other people make decisions so quickly!</li><li>I&#39;ve accepted the job and they want me to start next week.</li><li>The boss may need to contact you. Can you please give us your email?</li><li>This room was changed into a library.</li><li>There&#39;s a fence between the road and the White House.</li><li>How do we get to the city center.</li><li>It&#39;s difficult to understand the writing on the wall.</li><li>This mosque is very big.</li><li>He watched a film which was long and boring.</li><li>This documentary is in English.</li><li>What do you like about Washington, DC?</li><li>I watched a documentary about railroads yesterday.</li><li>We should take a break before we continue.</li><li>This is a new landmark, which was built in two thousand six.</li><li>The White House, which is very big, is the <strong>president&#39;s</strong> home.</li><li>Every weekend, people pray at the church.</li><li>City hall has been here for over twenty years.</li><li>Let&#39;s meet in town and have lunch.</li><li>Walk across this street, you will see the mosque.</li></ol><h2 id="_8" tabindex="-1"><a class="header-anchor" href="#_8"><span>8.</span></a></h2><ol><li>You studied engineering, right?</li><li>The job interview was great, but I need to make a decision tonight.</li><li>I&#39;m working two part-time jobs right now.</li><li>I studied engineering in college.</li><li>What benefits does your company offer?</li><li>I&#39;m applying for a new job, I really want to work there.</li><li>When you want a job, you have to <strong>apply</strong> for it. <ol><li><strong>apply for a job</strong>: ask to work</li></ol></li><li>On my resume, I wrote down all the jobs that I have ever had.</li><li>I quit my job because I had to move.</li><li>I&#39;ve <strong>done</strong> ten interviews. They&#39;ve offered me two jobs. I&#39;ve accepted one.</li><li>Can you please sign here? Your first and last name, please.</li><li>We would like you to work for us, Lisa. Please think about it, and talk to your family. Let us know when you&#39;ve made a decision. <ol><li>Lisa is maybe going to work for them.</li></ol></li><li>You&#39;ll get many benefits if work at our company. You can take a vacation every year too!</li><li>Kevin&#39;s wife got a great job in another city, so he has quit his job to move with her. He&#39;s a <strong>mechanic</strong>, and he hopes to find work soon. <ol><li>Kevin quit his job because he had to move.</li></ol></li><li>I&#39;ve studied business <strong>for</strong> many years. I&#39;ve done five international projects <strong>since</strong> 2018.</li><li>Mia just finished college and has applied for a job as an accountant. She has always understood math, and she really enjoys business. <ol><li>Mia is good at math.</li></ol></li><li>I started my career as a secretary.</li><li>Fifty people applied for the same job.</li><li>How many chapters does this book have?</li><li>We were late to class and Ben was walking slowly, so I told him <strong>to hurry up</strong>.</li><li>What is your essay about?</li><li>Anna lives in a dorm because she is a college student.</li><li>We need to go now! Hurry up!</li><li>All of the student&#39;s answers were incorrect, so he failed the test.</li><li>Welcome to your new dorm! I&#39;m Emma. Room 210 is upstairs on the second floor. There&#39;s also a bathroom and a small kitchen there. <ol><li>Emma is in a building where students sleep and study.</li></ol></li><li>Yesterday he asked me <strong>to</strong> write an essay for him. Ben always asks me <strong>for</strong> help.</li><li>Excuse me, Professor Lee. I have a question. Did you tell us to study Chapter 9 and 10 for homework, or just Chapter 9? <ol><li>What is the speaker asking? <ol><li>How much should they read?</li></ol></li><li>The speaker is professor Lee&#39;s student.</li></ol></li><li>No, I don&#39;t want to be late. Hurry up!</li><li>About two hundred students live in my dorm.</li><li>I failed the exam because all my answers were incorrect.</li><li>Chapter 1 has only three pages.</li><li>Oh no. The president said something incorrect again.</li><li>Is it a written exam, or do we have to speak?</li><li>I joined the intermediate class because I passed the <strong>beginner</strong> class, but I&#39;m not ready for the <strong>advanced</strong> level.</li><li>Mr. Parks asked me <strong>to explain</strong> the meaning of that word.</li><li>Do you know the meaning of this word?</li><li>I&#39;m nervous about the written exam because I don&#39;t like <strong>writing essays</strong>.</li><li>Today&#39;s test was hard! If this is the intermediate class, the advanced class is going to be even more difficult! <ol><li>The speaker took a test.</li></ol></li><li>The teacher told me <strong>to sit</strong> in the first row. He said, “Ben, <strong>sit</strong> next to Anna.”</li><li>Ryan takes a lot of notes during class. At night, he reviews his notes and tries to remember the most important information. <ol><li>After Ryan takes notes he studies them.</li><li>Ryan studies his notes at night.</li></ol></li><li>I told Ben <strong>to say</strong> the meaning of the words. I said, “Ben, <strong>say</strong> the meaning of this word in English.”</li><li>The teacher told Ben to sit in the front row of seats.</li><li>It&#39;s a written test, so bring a pen or pencil.</li><li>Yes, I&#39;m reviewing the words for the test.</li><li>I like to sit in the front row because I can talk to the teacher.</li><li>I am in the second row.</li><li>I don&#39;t know how to translate that word into French.</li><li>Do you know which words we should underline?</li><li>Let&#39;s read the descriptions in the book together.</li><li>将每个描述与正确的图片配对。 <ol><li><strong>Put</strong> each description <strong>together</strong> with the correct picture.</li></ol></li></ol><h2 id="_9" tabindex="-1"><a class="header-anchor" href="#_9"><span>9.</span></a></h2><ol><li>Do you know why the answers are so confusing?</li><li>We need to translate these Spanish sentences into English.</li><li>The teacher told us to read two stories. Then he asked, “How are the stories similar, and how are they different? Which is your favorite?” <ol><li>The students needed to answer some questions.</li></ol></li><li>你知道这描述的是谁吗？ <ol><li>Do you know <strong>who this is a description of</strong>?</li></ol></li><li>Excuse me, Professor. This question <strong>on</strong> the test is a little confusing. It says, “Choose the correct answer”, but I don&#39;t see any answers! <ol><li>The student don&#39;t know where the answers are.</li><li>The student is asking for help.</li></ol></li><li>Hey, do you know what we need to underline?</li><li>This assignment is too confusing. Tom, do you know what we need to do?</li><li>The <strong>similar</strong> girls are not sisters.</li><li>Yes, please write short descriptions.</li><li>I wanted to show that this word is important, so I underline it.</li><li>No, just translate them into French.</li><li>When is our next history lecture?</li><li>I hate waiting for my exam results. I&#39;m so nervous to know how <strong>well</strong> I <strong>did</strong>.</li><li>My friends and I always eat together at the dining hall.</li><li>The biology student <strong>wore</strong> blue gloves to visit her professor&#39;s laboratory.</li><li>I&#39;m not happy with my exam results, so I have to study more.</li><li>After a long exam, the students went to the dining hall. They were hungry.</li><li>There&#39;s a really nice pen on my desk, but it&#39;s not mine. All my pens are black, but this one is blue. Whose pen is it? <ol><li>He doesn&#39;t know who put the pen on his desk.</li><li>The speaker is asking about something that isn&#39;t his.</li></ol></li><li>Do you know <strong>why</strong> that lecture is so boring? And <strong>why does</strong> the lecture always finish late?</li><li>Ask Tom if you have a question about your science test. He loves science, especially chemistry. I think he&#39;s in the <strong>laboratory</strong> now! <ol><li>They&#39;re talking about Tom&#39;s favorite subject.</li></ol></li><li>Do you know where the laboratory is? And where does Tom usually study?</li><li>Whose notebook is this?</li><li>The result is a good <strong>grade</strong>.</li><li>Did you understand the professor&#39;s lecture?</li><li>We&#39;ll get the exam results next Monday.</li><li>Sometimes I eat breakfast at <strong>the dining hall</strong> before class.</li><li>I like listening to Mrs. Smith&#39;s lectures.</li><li>At the end of the semester, we&#39;ll attend an art show.</li><li>Do you know when we will get our certificates?</li><li>Mia needed information for her essay, so she did some research at the library.</li><li>A certificate is a document for students who have completed a course.</li><li>I think I&#39;ll pick advanced physics, English 2, and intermediate Spanish. How about you? Do you know what courses you&#39;re going to pick? <ol><li>They are talking about their next classes</li><li>They are picking classes at a college</li></ol></li><li>Do you know why the campus is so crowded?</li><li>Do you know where I can do some research for my project?</li><li>Next year I won&#39;t live <strong>on</strong> campus. I&#39;m going to move to an apartment downtown. I&#39;ll miss the dining hall, but maybe I&#39;ll learn to cook! <ol><li>He is talking about his plans</li></ol></li><li>Do you know why <strong>the students are</strong> attending that lecture today?</li><li>I want to do research about those plants.</li><li>What classes are you going to <strong>pick</strong> for next semester?</li><li>Junior is tired because he had to attend a boring lecture today.</li><li>Do you like living on campus?</li><li>Hi, Maria! I just got my results from our math test. I passed! Do you know what your results are? You probably did very well! <ol><li>The speaker wants to know Maria&#39;s results</li></ol></li><li>Do you know where I can print my certificate?</li><li>I have to read twenty chapters for <strong>homework</strong>.</li><li>This is the intermediate class, right?</li><li>Why are you still in the dorm? The class <strong>starts</strong> in ten minutes!</li><li>Let&#39;s review Chapter 10 for the test.</li><li>No, I need to do some research.</li><li>Chapter one has only three pages.</li><li>The words look similar, but they have different meanings.</li><li>Which app did you use to contact them?</li></ol><h2 id="_10" tabindex="-1"><a class="header-anchor" href="#_10"><span>10.</span></a></h2><ol><li>阅读作者对这座城市的描述。 <ol><li>Read the writer&#39;s description of the city.</li></ol></li><li>In China, the <strong>meaning</strong> of the color red is good luck. In France, the meaning of red is love. <ol><li>meaning: what something is</li></ol></li><li>Have you had a job interview in English before?</li><li>An <strong>airline</strong> is a company that flies airplanes and sells plane tickets. <ol><li>airline: airplane business</li></ol></li><li>Why do you want to work for our airline?</li><li>In class, we discussed the meaning of a song.</li><li>How long did you work for the airline?</li><li>Don&#39;t contact me on this app anymore.</li><li>What&#39;s the meaning of your name?</li><li>I&#39;d like a full-time job, so one day of work every week is not enough.</li><li>A <strong>dorm</strong> is a building where university students live and sleep. <ol><li>dorm: a home for college students</li></ol></li><li>Hurry up, we&#39;re going to be late!</li><li>Sorry, Ms. Lee is away from the office right now.</li><li>I&#39;ll be away until Friday, so I&#39;ll call Monday.</li><li>It&#39;s a full time job, so about forty.</li><li>Is it a part-time job?</li><li>Did you understand those confusing instructions?</li><li>If something is <strong>confusing</strong>, it is difficult to understand. <ol><li>confusing: without a clear reason</li></ol></li><li>This chapter is confusing, I need to study more.</li><li>When the boss is <strong>away</strong>, please ask customers to call again later. <ol><li>away: not here</li></ol></li><li>If you pass the beginner class, you can take the <strong>intermediate</strong> class. Then, the advanced class is next. <ol><li>intermediate: not too easy, not too hard</li></ol></li><li>You work a <strong>part-time</strong> job for less than forty hours a week. <ol><li>part-time: for some of your time</li></ol></li><li>I&#39;ve also begun making websites.</li><li><strong>Intermediate</strong> students already took the beginner class.</li><li>The intermediate class is still too hard for me.</li><li>So are you going to accept the job?</li><li>There&#39;s a really nice dining hall on campus.</li><li>Are you looking for a full time or part time job?</li><li>Benefits include over ten days <strong>of</strong> vacation.</li><li>Hurry up, we are late.</li><li>That strawberry cake is for dessert, not for dinner!</li><li>Do we have any fruit? <ol><li>No, I ate the last two strawberries yesterday.</li></ol></li><li>My favorite fish is <strong>tuna</strong>.</li><li>I&#39;m so tired! Let&#39;s order delivery for dinner. <ol><li>That&#39;s a good idea! How about something Chinese?</li></ol></li><li>There&#39;s some tuna in the fridge, but I don&#39;t want fish.</li><li>Why is there a dirty container on the table? <ol><li>Sorry, I ate the sandwiches and forgot to wash it.</li></ol></li><li>I&#39;m going to order delivery because my fridge is empty.</li><li>I want to make a strawberry cake, but we don&#39;t have any strawberries.</li><li>How <strong>much</strong> milk is in that container? And how <strong>many</strong> boxes of cookies do we have?</li><li>Oscar is not going to drink this wine. It smells terrible!</li><li>There isn&#39;t <strong>much</strong> sugar in the container, but there are <strong>many</strong> cookies!</li><li>Does this milk smell OK to you?</li><li>This restaurant has very few photos. Have you ordered from there before? <ol><li>Yes, don&#39;t worry. They make the best pizza!</li></ol></li><li>Everything from Billy&#39;s <strong>Barbecue</strong> tastes delicious!</li><li>I&#39;m going to order a salad. Would you like to share it? <ol><li>No, thank you! I&#39;m <strong>allergic</strong> to tomatoes.</li></ol></li><li>This website is the best way to order food! The delivery is very fast!</li><li>I have <strong>very few</strong> ingredients, but I need to bake <strong>a</strong> cake for ten people!</li><li>I really want <strong>a</strong> tuna sandwich, but <strong>very few</strong> restaurants make good sandwiches.</li><li>One way to buy tuna fish is in a can. Another way is to buy it fresh.</li><li>To cook a dish, you need to mix the ingredients together.</li></ol>',27)]))}const d=i(s,[["render",a]]),g=JSON.parse(`{"path":"/duolingo/sentence/sorted/19.html","title":"Section 19","lang":"en-US","frontmatter":{"description":"Section 19 1. Zari has to read five chapters of this book tonight. This app is a bit confusing, isn't it? You take intermediate physics before advanced physics. Sorry, but that ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Section 19\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2025-08-20T04:25:43.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Alice\\",\\"url\\":\\"https://github.com/AliceArchived\\"}]}"],["meta",{"property":"og:url","content":"https://alicearchived.github.io/english/duolingo/sentence/sorted/19.html"}],["meta",{"property":"og:site_name","content":"English Study Record"}],["meta",{"property":"og:title","content":"Section 19"}],["meta",{"property":"og:description","content":"Section 19 1. Zari has to read five chapters of this book tonight. This app is a bit confusing, isn't it? You take intermediate physics before advanced physics. Sorry, but that ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"en-US"}],["meta",{"property":"og:updated_time","content":"2025-08-20T04:25:43.000Z"}],["meta",{"property":"article:modified_time","content":"2025-08-20T04:25:43.000Z"}]]},"git":{"createdTime":1755663943000,"updatedTime":1755663943000,"contributors":[{"name":"Alice","username":"Alice","email":"alys8715ia@gmail.com","commits":1,"url":"https://github.com/Alice"}]},"readingTime":{"minutes":24.8,"words":7441},"filePathRelative":"duolingo/sentence/sorted/19.md","excerpt":"\\n<h2>1.</h2>\\n<ol>\\n<li>Zari has to read five chapters <strong>of</strong> this book tonight.</li>\\n<li>This app is a bit confusing, isn't it?</li>\\n<li>You take intermediate <strong>physics</strong> before advanced physics.</li>\\n<li>Sorry, but that answer is incorrect.</li>\\n<li>All the university buildings are <strong>on</strong> campus.</li>\\n<li>Hey, Kevin! Did you finish your essay? The professor told us to write two pages, right? I only have one page right now.\\n<ol>\\n<li>The speaker is Kevin's classmate.</li>\\n</ol>\\n</li>\\n<li>My professor has asked three of us to do research with her next fall. I'm very excited because we can learn so much from her!\\n<ol>\\n<li>He's excited because he's going to learn more.</li>\\n</ol>\\n</li>\\n<li>Professor Lee told us to change our incorrect answers.</li>\\n<li>I always ask Anna <strong>for</strong> help. I asked her <strong>to</strong> take me to my dorm.</li>\\n<li>Which class should I pick?</li>\\n<li>Yes, but it doesn't smell good. We shouldn't use it.</li>\\n<li>We only have <strong>a few</strong> hot dogs and some strawberries. Let's order delivery …</li>\\n<li>I don't want to cook tonight. Let's order delivery!</li>\\n<li>What's inside that plastic container?</li>\\n<li>These cans are full of tuna. And they're so cheap!</li>\\n<li>We have so <strong>many</strong> containers in the fridge, but there isn't <strong>much</strong> food in there.</li>\\n<li>I'm so hungry, but there's nothing to eat in the fridge, only a few old potatoes. I have an idea! Let's order delivery!\\n<ol>\\n<li>What's the speaker's idea?</li>\\n<li>to buy dinner</li>\\n</ol>\\n</li>\\n<li>Do we need so <strong>many</strong> cans of tuna? We don't have <strong>much</strong> time now. Can we buy them later?</li>\\n<li>Something in the fridge smells awful! Maybe it's the tuna salad. It looks <strong>old</strong>. Oh, and it smells bad. Nobody should eat this!\\n<ol>\\n<li>Right now, the speaker is looking inside the fridge.</li>\\n</ol>\\n</li>\\n<li>I always use this delivery app.\\n<ol>\\n<li>Me too! They're always so fast!</li>\\n</ol>\\n</li>\\n<li>Our neighbor is cooking something and it smells delicious!</li>\\n<li>How long has the chicken been in that container?</li>\\n<li>Mia is allergic to bread. If she eats it, she gets sick.</li>\\n<li>I always check the ingredients because I can't eat eggs.</li>\\n<li>Wow, this food tastes so good! It's delicious.</li>\\n<li>I love this restaurant! Their sandwiches taste great!</li>\\n<li>This app is the best way to order delivery.</li>\\n<li>Every time Mia order food, she has to check the ingredients. If a sauce has milk in it, she can't eat it because she's <strong>allergic</strong> to milk.\\n<ol>\\n<li>What does Mia have to check?</li>\\n<li>what is in a dish.</li>\\n</ol>\\n</li>\\n<li>I have a delivery app on my phone, but there are very few restaurants in this neighborhood.</li>\\n<li>OK, let's order one cheese pizza. Kevin and Ben are allergic to cheese, so we'll get a few burgers, too. What else? Maybe a salad?\\n<ol>\\n<li>Kevin and Ben can't eat cheese.</li>\\n</ol>\\n</li>\\n<li>Lisa, <strong>very few</strong> restaurants are open today. Can I make you a burger instead?</li>\\n<li>I can eat very <strong>few</strong> dishes because I'm allergic to almost everything.</li>\\n<li>Yes, of course. But it tasted terrible.</li>\\n<li>That Italian restaurant knows the perfect way to make pizza!</li>\\n<li>Are their <strong>salads</strong> good?\\n<ol>\\n<li>Yes! Their ingredients are so fresh!</li>\\n</ol>\\n</li>\\n<li>This menu has very little good food <strong>on</strong> it. Can we try somewhere else?</li>\\n<li>Oh, this chicken soup doesn't look bad in the photo. I think I'll order it.</li>\\n<li>OK, Maria, what should we order? The steak looks good, but the chicken looks good, too. Maybe we can order both! What do you think?\\n<ol>\\n<li>They are trying to decide something.</li>\\n</ol>\\n</li>\\n<li>It's a great restaurant, but there's very <strong>little</strong> information online, so very <strong>few</strong> people know it.</li>\\n<li>It's late, and very <strong>few</strong> restaurants are still open. We have very <strong>little</strong> time to order.</li>\\n<li>Just talking about food makes me hungry!</li>\\n<li>That pineapple is green.</li>\\n<li>This jar is empty. I need to buy some cookies.</li>\\n<li>Great idea. How about pineapples.</li>\\n<li>Grilled vegetables look so good in this picture.</li>\\n<li>Do they really serve drinks in coconuts?</li>\\n<li>This yogurt smells <strong>sour</strong>. I'm going to add some honey.</li>\\n<li>My favorite beverage is orange juice.</li>\\n<li>Without sugar, <strong>lemonade</strong> can be very sour.</li>\\n<li>Do we have something to drink at home? Grilled fish makes me thirsty.</li>\\n</ol>","autoDesc":true}`);export{d as comp,g as data};
